def path2url(path):
    """
    returns path
    """
    if sys.platform.startswith('java'):
        href = os.path.abspath(path)
        return 'file:' + href.replace('\\', '/')
    else:
        return u'file:' + urllib.pathname2url(os.path.abspath(path))
